:root {
  --bg: #1b1f2a;
  --card: #2a3142;
  --ink: #f2f4f8;
  --muted: #aab3c5;
  --accent: #ffb703;
  --accent-press: #e09e00;
  --die: #f7f9fc;
  --pip: #1b1f2a;
  --focus: #7fd1ff;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background: radial-gradient(circle at 50% 0%, #2b3550, var(--bg) 70%);
  color: var(--ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 17px;
  line-height: 1.5;
}

.app {
  width: 100%;
  max-width: 480px;
  background: var(--card);
  border: 3px solid #3b4560;
  border-radius: 16px;
  padding: 24px 20px 28px;
  box-shadow: 0 12px 0 #141824, 0 18px 40px rgba(0, 0, 0, 0.45);
}

.title {
  margin: 0 0 20px;
  font-size: 1.5rem;
  text-align: center;
  letter-spacing: 0.02em;
}

.controls {
  display: grid;
  gap: 8px;
  margin-bottom: 22px;
}

.label {
  font-weight: 600;
  color: var(--muted);
  font-size: 0.95rem;
}

.select {
  width: 100%;
  padding: 12px 14px;
  font-size: 1rem;
  font-family: inherit;
  color: var(--ink);
  background: #202634;
  border: 2px solid #4a5675;
  border-radius: 10px;
  cursor: pointer;
}

.select:hover { border-color: var(--accent); }
.select:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }

.help {
  font-size: 0.9rem;
  color: var(--muted);
}

.btn {
  margin-top: 6px;
  padding: 14px 18px;
  font-size: 1.15rem;
  font-weight: 700;
  font-family: inherit;
  color: #1b1f2a;
  background: var(--accent);
  border: none;
  border-radius: 12px;
  cursor: pointer;
  box-shadow: 0 5px 0 var(--accent-press);
  transition: transform 0.05s ease, box-shadow 0.05s ease, background 0.15s ease;
}

.btn:hover { background: #ffc233; }
.btn:focus-visible { outline: 3px solid var(--focus); outline-offset: 3px; }
.btn:active {
  transform: translateY(4px);
  box-shadow: 0 1px 0 var(--accent-press);
}

.board {
  display: grid;
  gap: 16px;
  justify-items: center;
  padding: 18px 12px;
  background: #202634;
  border-radius: 12px;
  margin-bottom: 22px;
}

.dice-area {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  justify-content: center;
  min-height: 76px;
  align-items: center;
}

.die {
  width: 64px;
  height: 64px;
  background: var(--die);
  border-radius: 10px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(3, 1fr);
  padding: 8px;
  gap: 2px;
  box-shadow: inset 0 -4px 0 #c9d1de, 0 4px 0 #0d1018;
}

.pip {
  width: 12px;
  height: 12px;
  background: var(--pip);
  border-radius: 2px;
  align-self: center;
  justify-self: center;
}

.total {
  margin: 0;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--accent);
}

.history-title {
  margin: 0 0 10px;
  font-size: 1.05rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.history-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.history-item {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  background: #202634;
  border-radius: 8px;
  font-size: 0.98rem;
}

.history-dice { color: var(--muted); }
.history-total { font-weight: 700; color: var(--ink); }

.history-empty {
  margin: 0;
  color: var(--muted);
  font-size: 0.95rem;
}

@media (max-width: 400px) {
  .app { padding: 20px 14px 24px; }
  .die { width: 54px; height: 54px; padding: 6px; }
  .pip { width: 10px; height: 10px; }
}

(function () {
  "use strict";

  var countSelect = document.getElementById("dice-count");
  var rollBtn = document.getElementById("roll-btn");
  var diceArea = document.getElementById("dice-area");
  var totalEl = document.getElementById("total");
  var historyList = document.getElementById("history-list");
  var historyEmpty = document.getElementById("history-empty");

  var history = [];
  var MAX_HISTORY = 5;

  // Pip positions in a 3x3 grid (row, col), 0-indexed.
  var PIP_MAP = {
    1: [[1, 1]],
    2: [[0, 0], [2, 2]],
    3: [[0, 0], [1, 1], [2, 2]],
    4: [[0, 0], [0, 2], [2, 0], [2, 2]],
    5: [[0, 0], [0, 2], [1, 1], [2, 0], [2, 2]],
    6: [[0, 0], [0, 2], [1, 0], [1, 2], [2, 0], [2, 2]]
  };

  function createDie(value) {
    var die = document.createElement("div");
    die.className = "die";
    die.setAttribute("role", "img");
    die.setAttribute("aria-label", "Die showing " + value);

    var pips = PIP_MAP[value];
    for (var i = 0; i < pips.length; i++) {
      var pip = document.createElement("span");
      pip.className = "pip";
      pip.style.gridRow = String(pips[i][0] + 1);
      pip.style.gridColumn = String(pips[i][1] + 1);
      die.appendChild(pip);
    }
    return die;
  }

  function rollDie() {
    return Math.floor(Math.random() * 6) + 1;
  }

  function renderDice(values) {
    diceArea.innerHTML = "";
    for (var i = 0; i < values.length; i++) {
      diceArea.appendChild(createDie(values[i]));
    }
  }

  function renderHistory() {
    historyList.innerHTML = "";
    if (history.length === 0) {
      historyEmpty.hidden = false;
      return;
    }
    historyEmpty.hidden = true;
    for (var i = 0; i < history.length; i++) {
      var entry = history[i];
      var li = document.createElement("li");
      li.className = "history-item";

      var diceSpan = document.createElement("span");
      diceSpan.className = "history-dice";
      diceSpan.textContent = entry.dice.join(" + ");

      var totalSpan = document.createElement("span");
      totalSpan.className = "history-total";
      totalSpan.textContent = "= " + entry.total;

      li.appendChild(diceSpan);
      li.appendChild(totalSpan);
      historyList.appendChild(li);
    }
  }

  function roll() {
    var count = parseInt(countSelect.value, 10);
    var values = [];
    var total = 0;
    for (var i = 0; i < count; i++) {
      var v = rollDie();
      values.push(v);
      total += v;
    }

    renderDice(values);
    totalEl.textContent = "Total: " + total;

    history.unshift({ dice: values, total: total });
    if (history.length > MAX_HISTORY) {
      history.length = MAX_HISTORY;
    }
    renderHistory();
  }

  rollBtn.addEventListener("click", roll);

  // Initial display: show one die placeholder face so the board isn't empty.
  renderDice([1]);
  totalEl.textContent = "Total: 0";
  renderHistory();
})();
